const services = [
  {
    name: "Concierge Digital con IA",
    category: "Inteligencia Artificial & Reservas 24/7",
    price: "Setup desde $350.000 ARS llave en mano",
    description: "Asistente virtual autónomo 24/7 multilingüe (español, inglés, portugués). Sincronización bidireccional en tiempo real con Google Calendar para agendar catas, visitas, turnos o habitaciones sin solapamientos. Fomenta la venta directa D2C ahorrando 15% a 20% en comisiones de OTAs (Booking, etc.).",
    tags: ["chatbot", "ia", "reservas", "google calendar", "whatsapp", "enoturismo", "hoteles", "bodegas", "consultorios", "atencion 24/7"],
    link: "concierge-ia.html"
  },
  {
    name: "Menú QR para Gastronomía",
    category: "Cartas Digitales Interactivas",
    price: "Planes accesibles a medida por local",
    description: "Cartas digitales de ultra alta velocidad para restaurantes, bares, cafeterías y bodegas. Actualización instantánea de precios y platos del día sin gastos de reimpresión en papel. Detección automática de idiomas para turistas extranjeros, fotos HD y derivación de pedidos directos a WhatsApp.",
    tags: ["menu qr", "carta digital", "restaurantes", "cafeterias", "bares", "bodegas", "platos", "pedidos whatsapp"],
    link: "menu-qr.html"
  },
  {
    name: "Desarrollo Web & E-Commerce de Alta Conversión",
    category: "Ingeniería Web & Tiendas Online",
    price: "Cotización personalizada según catálogo y alcance",
    description: "Plataformas web y tiendas online D2C con velocidad de carga sub-segundo (<1s) y puntaje Google Lighthouse >95 para liderar en SEO. Checkout optimizado integrado con MercadoPago, Stripe y WhatsApp sin comisiones abusivas. Landing Pages B2B.",
    tags: ["desarrollo web", "ecommerce", "tienda online", "landing page", "mercadopago", "stripe", "seo", "velocidad sub-1s"],
    link: "desarrollo-web.html"
  },
  {
    name: "Auditoría de Stock Inteligente",
    category: "Control Operativo & Reconciliación en Tiempo Real",
    price: "Cotización personalizada según sucursales y volumen",
    description: "Blindaje de la rentabilidad operativa mediante cruce automático en tiempo real entre ventas de POS y existencias físicas de almacén. Detección inmediata de mermas, robos hormiga y desvíos con alertas automáticas por WhatsApp y correo antes de roturas de stock.",
    tags: ["control de stock", "inventario", "reconciliacion pos", "mermas", "perdidas", "alertas preventivas", "bodegas", "distribuidoras"],
    link: "auditoria-stock.html"
  }
];

const lines = services.map(s => {
  return '- ' + [
    s.name,
    s.category,
    'Precio: ' + s.price,
    'Tags: ' + s.tags.join(', '),
    'Descripción: ' + s.description,
    'Enlace: ' + s.link
  ].join(' | ');
});

const catalog = lines.join('\n');

return [{
  json: {
    catalog: catalog,
    totalServices: services.length,
    company: "DEVLANTIA Development Company",
    location: "Mendoza, Argentina",
    contactUrl: "#contacto"
  }
}];

const rawOutput = $input.item.json.output || '';
const webhookItem = $('Webhook Chatbot DEVLANTIA').item.json;
const body = webhookItem.body || webhookItem;
const sessionId = body.sessionId || 'devlantia-session';

const lower = rawOutput.toLowerCase();
let chips = [];

if (lower.includes('menu') || lower.includes('qr') || lower.includes('carta') || lower.includes('restaurante') || lower.includes('cafeteria')) {
  chips = [
    { label: '📱 Ver Menú QR en Vivo', prompt: 'Quiero ver el demo de Menú QR' },
    { label: '💰 Precios Menú QR', prompt: '¿Cuánto cuesta el Menú QR?' },
    { label: '📅 Agendar Demo', prompt: 'Quiero agendar una demo técnica' }
  ];
} else if (lower.includes('concierge') || lower.includes('calendar') || lower.includes('reserva') || lower.includes('chatbot') || lower.includes('bodega')) {
  chips = [
    { label: '🤖 Probar Concierge IA', prompt: 'Quiero probar el simulador de Concierge IA' },
    { label: '💰 Setup $350k ARS', prompt: '¿Qué incluye el Setup de $350.000 ARS?' },
    { label: '📅 Agendar Demo', prompt: 'Quiero agendar una demo técnica' }
  ];
} else if (lower.includes('web') || lower.includes('ecommerce') || lower.includes('tienda') || lower.includes('landing')) {
  chips = [
    { label: '🌐 Calculadora ROI Web', prompt: 'Quiero ver el showcase de Desarrollo Web' },
    { label: '⚡ Velocidad sub-1s', prompt: '¿Por qué la velocidad sub-1s mejora ventas?' },
    { label: '📅 Solicitar Cotización', prompt: 'Quiero cotizar un sitio web o tienda' }
  ];
} else if (lower.includes('stock') || lower.includes('inventario') || lower.includes('merma') || lower.includes('almacen')) {
  chips = [
    { label: '📦 Simulador de Stock', prompt: 'Quiero probar el simulador de Auditoría de Stock' },
    { label: '📉 Control de Mermas', prompt: '¿Cómo detecta las mermas de stock?' },
    { label: '📅 Agendar Diagnóstico', prompt: 'Quiero agendar un diagnóstico de stock' }
  ];
} else {
  chips = [
    { label: '📱 Menú QR Gastronómico', prompt: 'Explicame el servicio de Menú QR' },
    { label: '🤖 Concierge con IA', prompt: 'Explicame el Concierge Digital con IA' },
    { label: '🌐 Desarrollo Web', prompt: 'Explicame Desarrollo Web & E-Commerce' },
    { label: '📦 Auditoría de Stock', prompt: 'Explicame Auditoría de Stock' },
    { label: '💰 Precios y Setup', prompt: '¿Cuáles son los precios de los servicios?' }
  ];
}

return [{
  json: {
    output: rawOutput,
    chips: chips,
    sessionId: sessionId,
    status: 'success',
    engine: 'n8n-ollama-ai'
  }
}];
